#!/usr/bin/env python3
"""Entry for make.fun news-image-20261117: "Sum up 17 November's world news in one image."

Writes the finished front page to /output/entry.png. The page - a one-page
broadsheet of Tuesday 17 November 2026 with 50 stories, drawn with PIL during
the recorded build sessions - is embedded below as base64 and restored byte
for byte, so every run produces identical output. Standard library only.
"""
import base64
import os

IMAGE_B64 = ""


def main() -> None:
    data = base64.b64decode(IMAGE_B64)
    # Integrity guard: refuse to emit anything but the finished PNG page.
    assert data[:8] == b"\x89PNG\r\n\x1a\n", "embedded payload is not a PNG"
    assert len(data) <= 1024 * 1024, "image exceeds the 1 MiB cap"
    out_dir = "/output"
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, "entry.png")
    with open(path, "wb") as fh:
        fh.write(data)
    print(f"wrote {path} ({len(data)} bytes)")


if __name__ == "__main__":
    main()
